import clsx from 'clsx';
import React, { ElementType, ReactElement, forwardRef } from 'react';

import { pseudoElementCSS, surfaceCSS } from './Surface.sty.js';
import { _useAriaLabelingProps } from '../../core/hooks/useAriaLabelingProps.js';
import { useFocusRing } from '../../core/styles/useFocusRing.js';
import type { AriaLabelingProps } from '../../core/types/a11y-props.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { PolymorphicComponentProps } from '../../core/types/polymorph.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { mergeProps as _mergeProps } from '../../core/utils/merge-props.js';
import { getSpacingSprinkles } from '../../styles/getSpacingSprinkles.js';
import { useLayoutStyles } from '../hooks/useLayoutStyles.js';
import type { LayoutProps } from '../types/layout.types.js';

//#region Typings

/** Accepted properties for Surface */
export interface SurfaceOwnProps
  extends AriaLabelingProps,
    LayoutProps,
    WithChildren,
    StylingProps,
    DataTestId {
  /**
   * Color of the border when the surface has focus or is selected.
   * @defaultValue 'neutral'
   */
  color?: 'neutral' | 'primary' | 'success' | 'critical' | 'warning';
  /**
   * Defines if the surface is selected and should indicate that state with a border.
   * @defaultValue false
   */
  selected?: boolean;
  /**
   * Indicates if the surface is currently dragged and then applies the corresponding styles.
   * @defaultValue false
   */
  dragged?: boolean;
  /**
   * Defines the surface's elevation to the background.
   * @defaultValue 'flat'
   */
  elevation?: 'flat' | 'raised' | 'floating';
}

// Merge own props with others inherited from the underlying element type
export type SurfaceProps<E extends ElementType> = PolymorphicComponentProps<
  E,
  SurfaceOwnProps
>;
//#endregion

/** The Surface component is used to structure content on a page. */
export const Surface: <E extends ElementType = 'div'>(
  props: SurfaceProps<E>,
) => ReactElement | null = /* @__PURE__ */ forwardRef(
  <E extends ElementType>(
    props: SurfaceProps<E>,
    forwardedRef: typeof props.ref,
  ) => {
    const {
      elevation = 'flat',
      dragged = false,
      selected = false,
      color = 'neutral',
      children,
      className: consumerClassName,
      style: consumerStyle,
      'data-testid': dataTestId,
      as,
      ...remainingProps
    }: SurfaceProps<E> = props;

    const ariaLabelingProps = _useAriaLabelingProps(remainingProps);

    const { layoutSizeStyles, remainingProps: surfaceProps } = useLayoutStyles(
      remainingProps,
      { paddingDefaults: { padding: 24 } },
    );

    const { focusProps, focusClassName } = useFocusRing({
      variant: color,
    });

    const surfaceMergedProps = {
      ..._mergeProps(
        // Need to cast this one as the inference of mergeProps would generate
        // a not allowed overlap. The remainingProps type is too complex due to the
        // polymorphic inheritance.
        surfaceProps as Record<string, unknown>,
        focusProps,
        ariaLabelingProps,
      ),
    };

    const Component = as ?? 'div';

    return (
      <Component
        {...surfaceMergedProps}
        data-testid={dataTestId}
        ref={forwardedRef}
        className={clsx(
          'strato-surface',
          surfaceCSS({ color, selected }),
          focusClassName,
          consumerClassName,
          getSpacingSprinkles(remainingProps, { padding: 24 }),
        )}
        style={{ ...layoutSizeStyles, ...consumerStyle }}
      >
        <div
          className={clsx(
            'surface-background',
            pseudoElementCSS({ elevation, dragged }),
          )}
          aria-hidden={true}
        />
        {children}
      </Component>
    );
  },
);
